#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ParseSettings { pub allow_missing_required: bool, pub reject_null_required: bool }
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AppProfile { pub endpoint: Option<String>, pub pool_size: u16, pub tracing: bool }
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ProfileError {
    Malformed { segment: usize }, UnknownKey(String), DuplicateKey(String), MissingEndpoint, NullEndpoint,
    InvalidValue { key: String, value: String },
}

pub fn parse_profile(input: &str, settings: ParseSettings) -> Result<AppProfile, ProfileError> {
    let mut endpoint: Option<Option<String>> = None;
    let mut pool_size = None;
    let mut tracing = None;
    if !input.trim().is_empty() {
        for (segment, raw) in input.split(';').enumerate() {
            let raw = raw.trim();
            if raw.is_empty() { return Err(ProfileError::Malformed { segment }); }
            let (key, value) = raw.split_once('=').ok_or(ProfileError::Malformed { segment })?;
            let key = key.trim(); let value = value.trim();
            match key {
                "endpoint" => {
                    if endpoint.is_some() { return Err(ProfileError::DuplicateKey(key.into())); }
                    endpoint = Some(if value == "null" { None } else { Some(value.into()) });
                }
                "pool_size" => {
                    if pool_size.is_some() { return Err(ProfileError::DuplicateKey(key.into())); }
                    let parsed = value.parse::<u16>().ok().filter(|v| (1..=1024).contains(v))
                        .ok_or_else(|| ProfileError::InvalidValue { key: key.into(), value: value.into() })?;
                    pool_size = Some(parsed);
                }
                "tracing" => {
                    if tracing.is_some() { return Err(ProfileError::DuplicateKey(key.into())); }
                    tracing = Some(match value { "true" => true, "false" => false, _ => return Err(ProfileError::InvalidValue { key: key.into(), value: value.into() }) });
                }
                _ => return Err(ProfileError::UnknownKey(key.into())),
            }
        }
    }
    let endpoint = match endpoint {
        Some(None) if settings.reject_null_required && !settings.allow_missing_required => return Err(ProfileError::NullEndpoint),
        Some(value) => value,
        None if !settings.allow_missing_required => return Err(ProfileError::MissingEndpoint),
        None => None,
    };
    Ok(AppProfile { endpoint, pool_size: pool_size.unwrap_or(12), tracing: tracing.unwrap_or(false) })
}

