#[path = "solution.rs"]
mod solution;
use solution::*;

fn settings(allow: bool, reject_null: bool) -> ParseSettings {
    ParseSettings { allow_missing_required: allow, reject_null_required: reject_null }
}

#[test]
fn parses_values_with_trimming_and_defaults() {
    assert_eq!(parse_profile(" endpoint = https://example.test ; pool_size=1024 ; tracing=true ", settings(false, false)), Ok(AppProfile {
        endpoint: Some("https://example.test".into()), pool_size: 1024, tracing: true,
    }));
    assert_eq!(parse_profile("endpoint=", settings(false, false)), Ok(AppProfile {
        endpoint: Some(String::new()), pool_size: 12, tracing: false,
    }));
    assert_eq!(parse_profile("pool_size=1;endpoint=x", settings(false, false)), Ok(AppProfile {
        endpoint: Some("x".into()), pool_size: 1, tracing: false,
    }));
}

#[test]
fn missing_and_null_endpoint_settings_are_distinct() {
    assert_eq!(parse_profile("   ", settings(false, false)), Err(ProfileError::MissingEndpoint));
    assert_eq!(parse_profile("", settings(true, true)), Ok(AppProfile {
        endpoint: None, pool_size: 12, tracing: false,
    }));
    assert_eq!(parse_profile("endpoint=null", settings(false, false)), Ok(AppProfile {
        endpoint: None, pool_size: 12, tracing: false,
    }));
    assert_eq!(parse_profile("endpoint = null", settings(true, true)), Err(ProfileError::NullEndpoint));
    assert_eq!(parse_profile("endpoint=null", settings(false, true)), Err(ProfileError::NullEndpoint));
}

#[test]
fn malformed_unknown_and_duplicate_errors_follow_segment_order() {
    assert_eq!(parse_profile("endpoint=x;;tracing=true", settings(false, false)), Err(ProfileError::Malformed { segment: 1 }));
    assert_eq!(parse_profile("endpoint", settings(false, false)), Err(ProfileError::Malformed { segment: 0 }));
    assert_eq!(parse_profile("endpoint=x; mystery=v", settings(false, false)), Err(ProfileError::UnknownKey("mystery".into())));
    assert_eq!(parse_profile("pool_size=bad;pool_size=4", settings(true, false)), Err(ProfileError::InvalidValue {
        key: "pool_size".into(), value: "bad".into(),
    }));
    assert_eq!(parse_profile("pool_size=4;pool_size=bad", settings(true, false)), Err(ProfileError::DuplicateKey("pool_size".into())));
}

#[test]
fn typed_values_are_strict_and_bounded() {
    for value in ["0", "1025", "-1", "abc"] {
        let input = format!("endpoint=x;pool_size={value}");
        assert_eq!(parse_profile(&input, settings(false, false)), Err(ProfileError::InvalidValue {
            key: "pool_size".into(), value: value.into(),
        }));
    }
    for value in ["True", "1", "yes", ""] {
        let input = format!("endpoint=x;tracing={value}");
        assert_eq!(parse_profile(&input, settings(false, false)), Err(ProfileError::InvalidValue {
            key: "tracing".into(), value: value.into(),
        }));
    }
}

